CREATE POLICY "Owners delete verification documents of a draft or withdrawn re" ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated USING (((bucket_id = 'verification-documents'::text) AND ((storage.foldername(name))[1] = ( SELECT (auth.uid())::text AS uid)) AND (NOT (EXISTS ( SELECT 1
   FROM verification_requests r
  WHERE (((r.id)::text = (storage.foldername(objects.name))[2]) AND (r.status <> 'unverified'::text)))))));
CREATE POLICY "Owners read their verification documents" ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING (((bucket_id = 'verification-documents'::text) AND ((storage.foldername(name))[1] = ( SELECT (auth.uid())::text AS uid))));
CREATE POLICY "Owners replace verification documents in a draft" ON storage.objects AS PERMISSIVE FOR UPDATE TO authenticated USING (((bucket_id = 'verification-documents'::text) AND ((storage.foldername(name))[1] = ( SELECT (auth.uid())::text AS uid)) AND (EXISTS ( SELECT 1
   FROM verification_requests r
  WHERE (((r.id)::text = (storage.foldername(objects.name))[2]) AND (r.profile_id = ( SELECT auth.uid() AS uid)) AND (r.status = 'unverified'::text)))))) WITH CHECK (((bucket_id = 'verification-documents'::text) AND ((storage.foldername(name))[1] = ( SELECT (auth.uid())::text AS uid)) AND (EXISTS ( SELECT 1
   FROM verification_requests r
  WHERE (((r.id)::text = (storage.foldername(objects.name))[2]) AND (r.profile_id = ( SELECT auth.uid() AS uid)) AND (r.status = 'unverified'::text))))));
CREATE POLICY "Owners upload verification documents to a draft" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'verification-documents'::text) AND ((storage.foldername(name))[1] = ( SELECT (auth.uid())::text AS uid)) AND (EXISTS ( SELECT 1
   FROM verification_requests r
  WHERE (((r.id)::text = (storage.foldername(objects.name))[2]) AND (r.profile_id = ( SELECT auth.uid() AS uid)) AND (r.status = 'unverified'::text))))));
CREATE POLICY "Users delete their own profile images" ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated USING (((bucket_id = ANY (ARRAY['avatars'::text, 'covers'::text])) AND ((storage.foldername(name))[1] = ( SELECT (auth.uid())::text AS uid))));
CREATE POLICY "Users read their own profile images" ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING (((bucket_id = ANY (ARRAY['avatars'::text, 'covers'::text])) AND ((storage.foldername(name))[1] = ( SELECT (auth.uid())::text AS uid))));
CREATE POLICY "Users replace their own profile images" ON storage.objects AS PERMISSIVE FOR UPDATE TO authenticated USING (((bucket_id = ANY (ARRAY['avatars'::text, 'covers'::text])) AND ((storage.foldername(name))[1] = ( SELECT (auth.uid())::text AS uid)))) WITH CHECK (((bucket_id = ANY (ARRAY['avatars'::text, 'covers'::text])) AND ((storage.foldername(name))[1] = ( SELECT (auth.uid())::text AS uid))));
