INSERT INTO supabase_migrations.schema_migrations SELECT * FROM json_populate_recordset(NULL::supabase_migrations.schema_migrations, $dump$[{"created_by": "apikey@lovable.dev", "idempotency_key": "04e04087-04e4-4f4f-ab94-4c9dc51e95f3", "name": "a9f10924-8770-4236-a053-38b83a547e33", "rollback": null, "statements": ["CREATE TABLE public.profiles (\n  id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,\n  username text UNIQUE,\n  display_name text,\n  headline text,\n  bio text,\n  city text,\n  roles text[] NOT NULL DEFAULT '{}',\n  avatar_url text,\n  availability text,\n  onboarding_complete boolean NOT NULL DEFAULT false,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;\nGRANT SELECT ON public.profiles TO anon;\nGRANT ALL ON public.profiles TO service_role;\nALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Profiles are viewable by everyone\" ON public.profiles FOR SELECT USING (true);\nCREATE POLICY \"Users can insert their own profile\" ON public.profiles FOR INSERT TO authenticated WITH CHECK (auth.uid() = id);\nCREATE POLICY \"Users can update their own profile\" ON public.profiles FOR UPDATE TO authenticated USING (auth.uid() = id) WITH CHECK (auth.uid() = id);\n\nCREATE TABLE public.portfolio_items (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  title text NOT NULL,\n  kind text NOT NULL DEFAULT 'track',\n  description text,\n  role text,\n  collaborators text[] NOT NULL DEFAULT '{}',\n  cover_url text,\n  media_url text,\n  release_year int,\n  published boolean NOT NULL DEFAULT false,\n  sort_order int NOT NULL DEFAULT 0,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX portfolio_items_user_idx ON public.portfolio_items (user_id, sort_order);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.portfolio_items TO authenticated;\nGRANT SELECT ON public.portfolio_items TO anon;\nGRANT ALL ON public.portfolio_items TO service_role;\nALTER TABLE public.portfolio_items ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Published portfolio items are public\" ON public.portfolio_items FOR SELECT USING (published = true);\nCREATE POLICY \"Owners can read their own portfolio items\" ON public.portfolio_items FOR SELECT TO authenticated USING (auth.uid() = user_id);\nCREATE POLICY \"Owners can insert portfolio items\" ON public.portfolio_items FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);\nCREATE POLICY \"Owners can update portfolio items\" ON public.portfolio_items FOR UPDATE TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);\nCREATE POLICY \"Owners can delete portfolio items\" ON public.portfolio_items FOR DELETE TO authenticated USING (auth.uid() = user_id);\n\nCREATE OR REPLACE FUNCTION public.update_updated_at_column()\nRETURNS TRIGGER AS $$\nBEGIN\n  NEW.updated_at = now();\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SET search_path = public;\n\nCREATE TRIGGER update_profiles_updated_at BEFORE UPDATE ON public.profiles\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE TRIGGER update_portfolio_items_updated_at BEFORE UPDATE ON public.portfolio_items\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE OR REPLACE FUNCTION public.handle_new_user()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  INSERT INTO public.profiles (id, display_name, avatar_url)\n  VALUES (\n    NEW.id,\n    COALESCE(NEW.raw_user_meta_data ->> 'full_name', NEW.raw_user_meta_data ->> 'name', split_part(NEW.email, '@', 1)),\n    NEW.raw_user_meta_data ->> 'avatar_url'\n  )\n  ON CONFLICT (id) DO NOTHING;\n  RETURN NEW;\nEND;\n$$;\n\nCREATE TRIGGER on_auth_user_created\nAFTER INSERT ON auth.users\nFOR EACH ROW EXECUTE FUNCTION public.handle_new_user();"], "version": "20260902172915"}, {"created_by": "apikey@lovable.dev", "idempotency_key": "1b265e4d-72a0-4709-ae08-45d615394702", "name": "e724e1b1-a791-4b56-8228-3c321616ba15", "rollback": null, "statements": ["REVOKE EXECUTE ON FUNCTION public.handle_new_user() FROM anon, authenticated, PUBLIC;"], "version": "20260902172936"}, {"created_by": "apikey@lovable.dev", "idempotency_key": "35e3a307-7779-4fc1-8c8b-0a17025c9908", "name": "6078bf6e-f7df-4e60-b56b-83e9387ea142", "rollback": null, "statements": ["ALTER TABLE public.profiles\n  ADD COLUMN IF NOT EXISTS instruments text[] NOT NULL DEFAULT '{}'::text[],\n  ADD COLUMN IF NOT EXISTS genres text[] NOT NULL DEFAULT '{}'::text[],\n  ADD COLUMN IF NOT EXISTS languages text[] NOT NULL DEFAULT '{}'::text[],\n  ADD COLUMN IF NOT EXISTS specialisations text[] NOT NULL DEFAULT '{}'::text[],\n  ADD COLUMN IF NOT EXISTS work_modes text[] NOT NULL DEFAULT '{}'::text[],\n  ADD COLUMN IF NOT EXISTS intents text[] NOT NULL DEFAULT '{}'::text[],\n  ADD COLUMN IF NOT EXISTS contact_channels text[] NOT NULL DEFAULT '{}'::text[],\n  ADD COLUMN IF NOT EXISTS experience_level text,\n  ADD COLUMN IF NOT EXISTS country text,\n  ADD COLUMN IF NOT EXISTS state text,\n  ADD COLUMN IF NOT EXISTS visibility text NOT NULL DEFAULT 'public',\n  ADD COLUMN IF NOT EXISTS links jsonb NOT NULL DEFAULT '[]'::jsonb,\n  ADD COLUMN IF NOT EXISTS discovery_prefs jsonb NOT NULL DEFAULT '{}'::jsonb,\n  ADD COLUMN IF NOT EXISTS onboarding_step text,\n  ADD COLUMN IF NOT EXISTS onboarding_draft jsonb NOT NULL DEFAULT '{}'::jsonb;"], "version": "20260902185426"}, {"created_by": null, "idempotency_key": null, "name": "fix_profiles_visibility_rls", "rollback": null, "statements": ["DROP POLICY IF EXISTS \"Profiles are viewable by everyone\" ON public.profiles", "CREATE POLICY \"Public profiles are viewable by everyone\" ON public.profiles FOR SELECT USING (visibility = 'public' OR auth.uid() = id)"], "version": "20260910131500"}