INSERT INTO public.reviews SELECT * FROM json_populate_recordset(NULL::public.reviews, $dump$[{"author_name": "Tara Bose", "author_org": "Synths · producer", "author_profile_id": null, "body": "Paid on time, clear about the deal, and they actually pitched the record.", "context": "Release · Low Season EP", "created_at": "2026-09-14T08:14:16.637366+00:00", "id": "a85cde18-9558-5757-aaea-ac73632b1113", "rating": 5, "response": null, "target_profile_id": "846507b2-f5ff-4d77-9087-e0bf4ec4d99d", "target_studio_id": null}, {"author_name": "Kabir Nair", "author_org": "Mix & mastering engineer", "author_profile_id": null, "body": "Good briefs and fair rates. Feedback rounds ran a little long.", "context": "Mastering · Paper Lanterns", "created_at": "2026-09-14T08:14:16.637366+00:00", "id": "d2e3ac59-888a-5a1f-99ff-52e64a771f9f", "rating": 4, "response": null, "target_profile_id": "846507b2-f5ff-4d77-9087-e0bf4ec4d99d", "target_studio_id": null}, {"author_name": "Rahul Iyer", "author_org": "Producer · mix engineer", "author_profile_id": null, "body": "Arrived with clear references and left space in the song for everyone.", "context": "Session · Glasshouse", "created_at": "2026-09-14T08:14:16.637366+00:00", "id": "06dbde78-a74a-5af1-a6df-79a798b1099e", "rating": 5, "response": null, "target_profile_id": "472ea245-75bc-42ee-8fbb-db6d571ee5d0", "target_studio_id": null}, {"author_name": "Meera Raghav", "author_org": "Producer, Pune", "author_profile_id": null, "body": "Brought his own backline, was on time for soundcheck, and the set was tight.", "context": "Co-bill · Pune show", "created_at": "2026-09-14T08:14:16.637366+00:00", "id": "8932da35-2ca4-5139-8fdf-f8ec2b2b3ace", "rating": 5, "response": null, "target_profile_id": "472ea245-75bc-42ee-8fbb-db6d571ee5d0", "target_studio_id": null}, {"author_name": "Rhea D'Souza", "author_org": "Keys · session player", "author_profile_id": null, "body": "Backline was exactly as listed and the monitor mix was sorted before doors.", "context": "House band · weekend run", "created_at": "2026-09-14T08:14:16.637366+00:00", "id": "484bdf40-ed21-530e-a94f-6eee9ce9824c", "rating": 5, "response": null, "target_profile_id": "b727b6fa-87b3-416f-aa49-0e7418b77ebc", "target_studio_id": null}, {"author_name": "Kabir Menon", "author_org": "Artist, Bengaluru", "author_profile_id": null, "body": "Great room and a fair door split. Load-in timing was tight.", "context": "Headline night", "created_at": "2026-09-14T08:14:16.637366+00:00", "id": "17d27208-3a57-5deb-90dc-d17e88e927a8", "rating": 4, "response": null, "target_profile_id": "b727b6fa-87b3-416f-aa49-0e7418b77ebc", "target_studio_id": null}, {"author_name": "Arjun Pillai", "author_org": "Pianist · arranger", "author_profile_id": null, "body": "Knows exactly what the band should sound like in the room and gets there quickly.", "context": "Arrangement · Blue Hour Raga", "created_at": "2026-09-14T08:14:16.637366+00:00", "id": "9dde1670-2d9c-5a6e-a8a2-362227e7ad5a", "rating": 5, "response": null, "target_profile_id": "79d38ce7-8f99-4dbf-9a37-8a927c8f1166", "target_studio_id": null}, {"author_name": "Kabir Menon", "author_org": "Artist, Bengaluru", "author_profile_id": null, "body": "Easy to work with and very prepared. Soundcheck ran over.", "context": "Co-bill · Pune show", "created_at": "2026-09-14T08:14:16.637366+00:00", "id": "11c7ab0a-d2e7-5c42-8f92-634ea50fd0c9", "rating": 4, "response": null, "target_profile_id": "79d38ce7-8f99-4dbf-9a37-8a927c8f1166", "target_studio_id": null}, {"author_name": "Tara Bose", "author_org": "Synths · producer", "author_profile_id": null, "body": "The brief was written around the music, and the edit never fought the score.", "context": "Score · City of Echoes", "created_at": "2026-09-14T08:14:16.637366+00:00", "id": "2eaa6615-90bc-53de-9bdf-58c78c78af21", "rating": 5, "response": null, "target_profile_id": "87b8fccc-dcc1-49c2-af85-766faf3b5619", "target_studio_id": null}, {"author_name": "Sanya Rao", "author_org": "Artist manager", "author_profile_id": null, "body": "Clear schedules and quick approvals. The budget changed once mid-shoot.", "context": "Production liaison", "created_at": "2026-09-14T08:14:16.637366+00:00", "id": "9f7c6855-ead1-55f6-8810-b8cd75ebbaf0", "rating": 4, "response": null, "target_profile_id": "87b8fccc-dcc1-49c2-af85-766faf3b5619", "target_studio_id": null}, {"author_name": "The Quarter", "author_org": "Venue, Mumbai", "author_profile_id": null, "body": "Learns a set in one rehearsal and covers for anyone who's missing.", "context": "House band · weekend run", "created_at": "2026-09-14T08:14:16.637366+00:00", "id": "e9439a3b-8a2a-5e46-9577-b7d52fac4b10", "rating": 5, "response": null, "target_profile_id": "f24d3198-4025-478e-a4bf-7e1270688642", "target_studio_id": null}, {"author_name": "Tara Bose", "author_org": "Synths · producer", "author_profile_id": null, "body": "Programmed every patch before rehearsal. No time wasted.", "context": "Live session", "created_at": "2026-09-14T08:14:16.637366+00:00", "id": "5183684e-9bfe-54a2-aa62-145b7d3c4e11", "rating": 5, "response": null, "target_profile_id": "f24d3198-4025-478e-a4bf-7e1270688642", "target_studio_id": null}, {"author_name": "Meera Raghav", "author_org": "Producer, Pune", "author_profile_id": null, "body": "Charts arrived before the session and the string parts needed no fixes.", "context": "Arrangement · Blue Hour Raga", "created_at": "2026-09-14T08:14:16.637366+00:00", "id": "c2f1ced8-fa65-5274-b6c4-5a92c4a5615f", "rating": 5, "response": null, "target_profile_id": "48da93a3-2331-4b4c-bc7c-006464115ff4", "target_studio_id": null}, {"author_name": "Sunset Records", "author_org": "Independent label, Mumbai", "author_profile_id": null, "body": "Delivered stems early, and the synth parts carried the whole EP.", "context": "Release · Low Season EP", "created_at": "2026-09-14T08:14:16.637366+00:00", "id": "5beccc70-c29f-5636-a27f-dc31a4d12b48", "rating": 5, "response": null, "target_profile_id": "ff850259-fb61-4634-a850-f4d8c631feac", "target_studio_id": null}, {"author_name": "Northlight Films", "author_org": "Production house, Delhi", "author_profile_id": null, "body": "Scored to picture fast and took notes without fuss.", "context": "Score · City of Echoes", "created_at": "2026-09-14T08:14:16.637366+00:00", "id": "486a403c-2a75-52dd-828b-a0386a4a6ea2", "rating": 5, "response": null, "target_profile_id": "ff850259-fb61-4634-a850-f4d8c631feac", "target_studio_id": null}, {"author_name": "Rahul Iyer", "author_org": "Producer · mix engineer", "author_profile_id": null, "body": "Master v1 was already close. The vocal sits in front without getting harsh.", "context": "Mix · Raat Ki Rani", "created_at": "2026-09-14T08:14:16.637366+00:00", "id": "8a907728-2326-5c0f-abc4-f5a9df1a08ba", "rating": 5, "response": null, "target_profile_id": "9b76ac6a-6c04-42ae-955f-9e3233b02199", "target_studio_id": null}, {"author_name": "Sanya Rao", "author_org": "Artist manager", "author_profile_id": null, "body": "Stems were labelled and delivered on the dates we agreed.", "context": "Stems · Aftertaste", "created_at": "2026-09-14T08:14:16.637366+00:00", "id": "463704cc-c33f-56ec-92ba-940b8faa8f9d", "rating": 5, "response": null, "target_profile_id": "9b76ac6a-6c04-42ae-955f-9e3233b02199", "target_studio_id": null}, {"author_name": "Rahul Iyer", "author_org": "Producer · mix engineer", "author_profile_id": null, "body": "Room A sounds great with the band live, and the mics were up before we arrived.", "context": "Tracking · Monsoon Sessions", "created_at": "2026-09-14T08:14:16.637366+00:00", "id": "616c3e48-da56-5b44-97f6-d20b1f1dee7a", "rating": 5, "response": null, "target_profile_id": "2c29531c-68cf-4b7d-84e1-08ae729a6c69", "target_studio_id": null}, {"author_name": "Meera Raghav", "author_org": "Producer, Pune", "author_profile_id": null, "body": "Quick, clear quote with the backline listed. Weekends book out fast.", "context": "Enquiry · live tracking", "created_at": "2026-09-14T08:14:16.637366+00:00", "id": "dcb5ef44-8da4-584b-bef7-0bfa84b790f3", "rating": 4, "response": null, "target_profile_id": "2c29531c-68cf-4b7d-84e1-08ae729a6c69", "target_studio_id": null}, {"author_name": "Kabir Nair", "author_org": "Mix & mastering engineer", "author_profile_id": null, "body": "Every delivery date was agreed up front, and nobody chased me for files.", "context": "Liaison · Aftertaste", "created_at": "2026-09-14T08:14:16.637366+00:00", "id": "ebf9640e-42d2-5628-a2c3-90ca710a167c", "rating": 5, "response": null, "target_profile_id": "8a15fc73-c131-46f5-8cba-2c1c96aaa645", "target_studio_id": null}, {"author_name": "Ehsaan Q.", "author_org": null, "author_profile_id": null, "body": "Excellent phrasing and control. Subscribed!", "context": null, "created_at": "2026-06-18T09:00:00+00:00", "id": "122c4065-08bc-57ea-84c2-a807a83f6e38", "rating": 5, "response": null, "target_profile_id": "e82a88ea-8233-5661-838f-aa3082d23c01", "target_studio_id": null}, {"author_name": "James Miller", "author_org": "A&R Universal Records", "author_profile_id": null, "body": "The raw vocals recorded are exceptionally clean. The Kemper profile work was masterfully done.", "context": null, "created_at": "2026-06-25T09:00:00+00:00", "id": "73050502-a934-54c3-851d-3ed7c8294573", "rating": 5, "response": null, "target_profile_id": "87b3ca87-415c-5335-956d-b045501bbf50", "target_studio_id": null}, {"author_name": "Kabir Singh", "author_org": "Producer", "author_profile_id": null, "body": "Dolby Atmos stems came back flawless.", "context": null, "created_at": "2026-07-30T09:00:00+00:00", "id": "cbe74863-83d7-5f33-aed7-c00fedc61c51", "rating": 5, "response": null, "target_profile_id": "87b3ca87-415c-5335-956d-b045501bbf50", "target_studio_id": null}, {"author_name": "Pritam's Studio", "author_org": null, "author_profile_id": null, "body": "One take, every time.", "context": null, "created_at": "2026-05-22T09:00:00+00:00", "id": "127b73b2-0af0-5134-baa6-ed88dcd9e8a9", "rating": 4.9, "response": null, "target_profile_id": "715c16b9-286e-582e-950b-0613140cca38", "target_studio_id": null}, {"author_name": "Rohan Das", "author_org": "Vintage Synth Collector", "author_profile_id": null, "body": "Great ear for vintage synth tone.", "context": null, "created_at": "2026-05-14T09:00:00+00:00", "id": "32e05b06-87de-5024-a4c8-8b29f8381b0d", "rating": 4, "response": null, "target_profile_id": "87b3ca87-415c-5335-956d-b045501bbf50", "target_studio_id": null}, {"author_name": "Sanjay K.", "author_org": "Producer", "author_profile_id": null, "body": "Mix quality is film-ready straight out of the session.", "context": null, "created_at": "2026-06-01T09:00:00+00:00", "id": "69dc6db8-4a51-5b12-b0ab-2c2cb430ffa5", "rating": 4.8, "response": null, "target_profile_id": "87b3ca87-415c-5335-956d-b045501bbf50", "target_studio_id": null}, {"author_name": "Sarah Connor", "author_org": "Creative Director, Synergy Games", "author_profile_id": null, "body": "Delivered a soundtrack that elevated the entire game.", "context": null, "created_at": "2026-06-05T09:00:00+00:00", "id": "4c850fc6-f1b0-5636-99df-eaa9cebc4e7d", "rating": 5, "response": null, "target_profile_id": "87b3ca87-415c-5335-956d-b045501bbf50", "target_studio_id": null}, {"author_name": "T-Series A&R Team", "author_org": null, "author_profile_id": null, "body": "Exceptional range and control across genres.", "context": null, "created_at": "2026-06-10T09:00:00+00:00", "id": "d87458b1-eb53-5044-9529-f5151f425c07", "rating": 5, "response": null, "target_profile_id": "715c16b9-286e-582e-950b-0613140cca38", "target_studio_id": null}, {"author_name": "Arjun Mehta", "author_org": null, "author_profile_id": null, "body": "Mixed Monsoon Raga here — the Atmos room is genuinely world-class.", "context": null, "created_at": "2026-06-12T09:00:00+00:00", "id": "1ba0f44d-01a0-505b-b82f-36a8683c7899", "rating": 5, "response": null, "target_profile_id": null, "target_studio_id": "29833230-3ca8-58e3-b0c2-f87756c18008"}, {"author_name": "